
local __P = "lua"
local __D = ""

local bit32 = bit32 or (function()
    local ok, b = pcall(require, "bit")
    if ok then return b end
end)()

local band   = bit32.band
local bxor   = bit32.bxor
local rshift = bit32.rshift

local function imul32(a, b)
    local aLo = band(a, 0xFFFF)
    local aHi = rshift(a, 16)
    local bLo = band(b, 0xFFFF)
    local bHi = rshift(b, 16)
    local lo  = aLo * bLo
    local mid = band(aLo * bHi + aHi * bLo, 0xFFFF) * 0x10000
    return band(lo + mid, 0xFFFFFFFF)
end

local function deriveKey(password, salt)
    local s = password .. ":" .. salt
    local base = {s:byte(1, -1)}
    local state = 0x811C9DC5
    for r = 0, 999 do
        for i = 1, #base do
            state = bxor(state, base[i] + r)
            state = imul32(state, 0x01000193)
            state = bxor(state, rshift(state, 15))
        end
    end
    local key = {}
    for i = 1, 32 do
        state = bxor(state, rshift(state, 13))
        state = imul32(state, 0x5BD1E995)
        state = bxor(state, rshift(state, 15))
        key[i] = state % 256
    end
    return key
end

local B = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function b64d(str)
    str = str:gsub("[^" .. B .. "=]", "")
    local out = {}
    local i = 1
    while i <= #str do
        local c1 = (B:find(str:sub(i, i), 1, true) or 1) - 1
        local c2 = (B:find(str:sub(i+1, i+1), 1, true) or 1) - 1
        local c3 = (B:find(str:sub(i+2, i+2), 1, true) or 1) - 1
        local c4 = (B:find(str:sub(i+3, i+3), 1, true) or 1) - 1
        local n = c1 * 262144 + c2 * 4096 + c3 * 64 + c4
        out[#out+1] = string.char(math.floor(n / 65536) % 256)
        if str:sub(i+2, i+2) ~= "=" and str:sub(i+2, i+2) ~= "" then
            out[#out+1] = string.char(math.floor(n / 256) % 256)
        end
        if str:sub(i+3, i+3) ~= "=" and str:sub(i+3, i+3) ~= "" then
            out[#out+1] = string.char(n % 256)
        end
        i = i + 4
    end
    return table.concat(out)
end

local function rc4(data, key)
    local S = {}
    for i = 0, 255 do S[i] = i end
    local j = 0
    local klen = #key
    for i = 0, 255 do
        j = (j + S[i] + key[(i % klen) + 1]) % 256
        S[i], S[j] = S[j], S[i]
    end
    local out = {}
    local i2, j2 = 0, 0
    for n = 1, #data do
        i2 = (i2 + 1) % 256
        j2 = (j2 + S[i2]) % 256
        S[i2], S[j2] = S[j2], S[i2]
        out[n] = string.char(bxor(data:byte(n), S[(S[i2] + S[j2]) % 256]))
    end
    return table.concat(out)
end

local function xorRoll(data, key)
    local out = {}
    local klen = #key
    for i = 1, #data do
        out[i] = string.char(bxor(data:byte(i), key[((i - 1) % klen) + 1]))
    end
    return table.concat(out)
end

local k1 = deriveKey(__P, "1")
local k2 = deriveKey(__P, "2")
local k3 = deriveKey(__P, "3")

local source = rc4(xorRoll(rc4(b64d(__D), k3), k2), k1)

local fn, err = loadstring(source)
if not fn then error("[NewUp] " .. tostring(err)) end
return fn()
